{"content":"from analytics.report import weekly_report

def test_repro_conversion_rate():
    stats = {"visits": 1000, "signups": 450, "bounces": 300, "session_seconds": 125000, "sessions": 1000}
    report = weekly_report(stats)
    print(f"Report with 1000 visits:\n{report}")
    assert "Conversion: 45.0%" in report

def test_repro_zero_visits():
    stats = {"visits": 0, "signups": 0, "bounces": 0, "session_seconds": 0, "sessions": 0}
    try:
        report = weekly_report(stats)
        print(f"Report with 0 visits:\n{report}")
        assert "Conversion: 0.0%" in report
        assert "Bounce rate: 0.0%" in report
    except ZeroDivisionError:
        print("Caught ZeroDivisionError!")
        raise

if __name__ == "__main__":
    try:
        test_repro_conversion_rate()
        print("test_repro_conversion_rate passed")
    except Exception as e:
        print(f"test_repro_conversion_rate failed: {e}")

    try:
        test_repro_zero_visits()
        print("test_repro_zero_visits passed")
    except Exception as e:
        print(f"test_repro_zero_visits failed: {e}")
